-- "Ibogaine in the news" — five credited links and two story drafts, October 2026.
--
-- Every link below was opened and checked: outlet, byline, date and what it actually says. Blurbs are ours,
-- under 280 characters, no excerpt from the outlet. Links load as DRAFTS; an editor publishes them from
-- Admin → News feed, which puts them on /news-feed and in the "Ibogaine in the news" block on the cover.
--
-- NOT included, on purpose:
--   * CBS 60 Minutes, "U.S. veterans with PTSD take a psychedelic journey in Mexico" (16 Aug 2026) — that
--     segment is about PSILOCYBIN, not ibogaine. It does not belong in this feed.
--   * CNN, "What is ibogaine, and what does it treat?" (21 Sep 2026) and NBC News on the executive order —
--     both refuse automated reading, so no blurb could be written from the piece itself. An editor should
--     open them and add them by hand.

insert into public.news_links (site_id, url, title, source_name, published_on, blurb, tags, status)
select s.id, v.url, v.title, v.source_name, v.published_on::date, v.blurb, v.tags::text[], 'draft'
  from public.sites s
  cross join (values
    ('https://www.texastribune.org/2026/03/31/texas-ibogaine-research-clinical-trials-psychedelics/',
     'Texas will launch its own clinical trials into ibogaine psychedelic after failing to find a drug company to help',
     'The Texas Tribune', '2026-03-31',
     'Texas puts its $50 million into state-run trials at UTHealth Houston and UTMB after drug companies'' proposals fell short. An analyst warns the money may be hard to release without a private match, and that FDA approval would need far more.',
     '{policy,texas,funding}'),

    ('https://www.stripes.com/veterans/2026-04-20/ibogaine-treatment-psychedelics-executive-order-21432685.html',
     'Trump advances psychedelic review, joined by ex-SEALs',
     'Stars and Stripes', '2026-04-20',
     'The executive order sets aside $50 million and directs the FDA to speed its review of psilocybin and ibogaine. Ibogaine was the focus of the signing. It remains Schedule I, and the Stanford-linked study it cites gave it with magnesium under monitoring.',
     '{policy,veterans,federal}'),

    ('https://abc13.com/post/trauma-survivors-share-experience-psychedelic-texas-is-spending-millions-study/19396545/',
     'Powerful psychedelic drug ibogaine gets closer to FDA approval: Stories from Texans who have done it',
     'ABC13 Houston', '2026-06-27',
     'Houston station KTRK follows Texans who went to Mexico for ibogaine, including a father whose son has had eight surgeries since a brain injury. Patients are kept on a heart monitor. Those featured say it is too early to know how long the effects last.',
     '{treatment,texas,patients}'),

    ('https://www.foxnews.com/travel/elite-ceos-pay-20k-endure-psychedelic-hell-ride-rewires-human-brain',
     'Elite CEOs pay $20K to endure a psychedelic ''hell ride'' that rewires the human brain',
     'Fox News', '2026-10-04',
     'Fox reports executives paying $12,500 to $20,000 at Mexican clinics, one of them calling the flood dose a hell ride. It names clinics in Cancún and Playa del Carmen, notes expansion into Costa Rica, and says the drug carries a risk of fatal cardiac complications.',
     '{treatment,cost,risk}'),

    ('https://www.foxnews.com/video/6402953858112',
     'A look inside ibogaine drug treatment for veterans',
     'Fox News', '2026-10-04',
     'A Fox News segment inside ibogaine treatment for veterans. Confirm the broadcast date and programme against the recording before publishing this one.',
     '{veterans,broadcast}')
  ) as v(url, title, source_name, published_on, blurb, tags)
 where s.slug = 'eyetoday'
on conflict (site_id, url) do nothing;

-- ---------------------------------------------------------------------------
-- Story 1 — the coverage itself (News). Draft: needs a byline, a hero and Jeff's read.
-- ---------------------------------------------------------------------------
insert into public.articles (site_id, section_id, slug, title, dek, body_json, body_html, status, seo_description)
select s.id, sec.id,
       'ibogaine-has-gone-national-what-the-networks-are-saying',
       'Ibogaine has gone national. Here is what the networks are actually saying.',
       'Stars and Stripes, ABC13 Houston and Fox News have all covered ibogaine this year, from a White House signing ceremony to a $20,000 clinic room in Cancún. Read together, they agree on more than they disagree.',
       '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Six months ago ibogaine was a word you had to explain. This year it has been the subject of a presidential executive order, a $50 million line in the Texas budget, a Houston television news series and a Fox News feature about chief executives paying $20,000 a week in Mexico. The coverage has arrived from outlets with very different audiences, and that is the most useful thing about it: where they agree, they are probably describing something real."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What they agree on"}]},{"type":"paragraph","content":[{"type":"text","text":"Three facts turn up in every piece. Ibogaine is still a Schedule I drug in the United States, so the treatment described is happening in Mexico. People who have had it describe the result in terms journalists are not used to hearing about a medical intervention. And it can interfere with the heart."}]},{"type":"paragraph","content":[{"type":"text","text":"That last point is not a caveat the reporters added at the end. It is in the mechanics of every story. Stars and Stripes, covering the April signing ceremony, noted that the Stanford-linked study of 30 veterans gave oral ibogaine together with magnesium under medical monitoring. ABC13 Houston reported that patients are placed on a heart monitor because the drug can cause abnormal heart rhythms. Fox News, in October, put it most bluntly, describing a risk of potentially fatal cardiac complications and tying the renewed attention in part to a death following ibogaine travel to Mexico."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Where they differ"}]},{"type":"paragraph","content":[{"type":"text","text":"The difference is the door each outlet walks in through. Stars and Stripes came at it as policy and veterans'' access, reporting that former Navy SEAL Robert O''Neill, who said he had taken ibogaine three times, stood alongside other ex-SEALs and the podcaster Joe Rogan at the signing."}]},{"type":"paragraph","content":[{"type":"text","text":"ABC13 Houston came at it through patients: a father whose son has had eight surgeries since a 2021 brain injury, and a veteran who says the treatment eased his trauma. Both said it was too early to know how long the effects would hold."}]},{"type":"paragraph","content":[{"type":"text","text":"Fox News came at it through money, reporting fees of $12,500 to $20,000 at named clinics in Cancún and Playa del Carmen, citing a New York Times count of at least 40 Mexican clinics charging roughly $5,000 to $20,000, and quoting one patient calling his high-dose session a hell ride."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What none of them can tell you yet"}]},{"type":"paragraph","content":[{"type":"text","text":"How long it lasts. The study cited at the executive order measured improvement in PTSD, depression and anxiety at one month. The patients ABC13 spoke to volunteered that they did not know. No piece published this year reports a controlled trial with a comparison group and long follow-up, because none has been completed. That is what the Texas money and the federal review are meant to buy, and it is the gap every story above is standing beside."}]},{"type":"paragraph","content":[{"type":"text","text":"Eye Today tracks the trials, the funding and the legal status country by country. The coverage is new. The questions are not."}]}]}'::jsonb,
       '<p>Six months ago ibogaine was a word you had to explain. This year it has been the subject of a presidential executive order, a $50 million line in the Texas budget, a Houston television news series and a Fox News feature about chief executives paying $20,000 a week in Mexico. The coverage has arrived from outlets with very different audiences, and that is the most useful thing about it: where they agree, they are probably describing something real.</p><h2>What they agree on</h2><p>Three facts turn up in every piece. Ibogaine is still a Schedule I drug in the United States, so the treatment described is happening in Mexico. People who have had it describe the result in terms journalists are not used to hearing about a medical intervention. And it can interfere with the heart.</p><p>That last point is not a caveat the reporters added at the end. It is in the mechanics of every story. <a href="https://www.stripes.com/veterans/2026-04-20/ibogaine-treatment-psychedelics-executive-order-21432685.html">Stars and Stripes</a>, covering the April signing ceremony, noted that the Stanford-linked study of 30 veterans gave oral ibogaine together with magnesium under medical monitoring. <a href="https://abc13.com/post/trauma-survivors-share-experience-psychedelic-texas-is-spending-millions-study/19396545/">ABC13 Houston</a> reported that patients are placed on a heart monitor because the drug can cause abnormal heart rhythms. <a href="https://www.foxnews.com/travel/elite-ceos-pay-20k-endure-psychedelic-hell-ride-rewires-human-brain">Fox News</a>, in October, put it most bluntly, describing a risk of potentially fatal cardiac complications and tying the renewed attention in part to a death following ibogaine travel to Mexico.</p><h2>Where they differ</h2><p>The difference is the door each outlet walks in through. Stars and Stripes came at it as policy and veterans&rsquo; access, reporting that former Navy SEAL Robert O&rsquo;Neill, who said he had taken ibogaine three times, stood alongside other ex-SEALs and the podcaster Joe Rogan at the signing.</p><p>ABC13 Houston came at it through patients: a father whose son has had eight surgeries since a 2021 brain injury, and a veteran who says the treatment eased his trauma. Both said it was too early to know how long the effects would hold.</p><p>Fox News came at it through money, reporting fees of $12,500 to $20,000 at named clinics in Canc&uacute;n and Playa del Carmen, citing a New York Times count of at least 40 Mexican clinics charging roughly $5,000 to $20,000, and quoting one patient calling his high-dose session a hell ride.</p><h2>What none of them can tell you yet</h2><p>How long it lasts. The study cited at the executive order measured improvement in PTSD, depression and anxiety at one month. The patients ABC13 spoke to volunteered that they did not know. No piece published this year reports a controlled trial with a comparison group and long follow-up, because none has been completed. That is what the Texas money and the federal review are meant to buy, and it is the gap every story above is standing beside.</p><p>Eye Today tracks the <a href="https://theeye.today/tracker">trials and the funding</a>, and the <a href="https://theeye.today/legal-map">legal status country by country</a>. The coverage is new. The questions are not.</p>',
       'draft',
       'Stars and Stripes, ABC13 Houston and Fox News have all covered ibogaine this year. What the coverage agrees on, where it differs, and the question none of it can answer yet.'
  from public.sites s join public.sections sec on sec.site_id = s.id and sec.slug = 'news'
 where s.slug = 'eyetoday'
on conflict (site_id, slug) do nothing;

-- ---------------------------------------------------------------------------
-- Story 2 — the money and the law (Policy & Law). Draft.
-- ---------------------------------------------------------------------------
insert into public.articles (site_id, section_id, slug, title, dek, body_json, body_html, status, seo_description)
select s.id, sec.id,
       'fifty-million-dollars-and-a-schedule-i-problem',
       'Fifty million dollars, a federal order, and a Schedule I problem',
       'Texas committed $50 million to ibogaine trials and a federal executive order promised at least as much again. Neither changes the drug''s legal status, and the state money comes with a condition it has not yet met.',
       '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The headline number is $100 million: $50 million from Texas and at least $50 million attached to a federal executive order signed in April. Both are real. Neither is money in a researcher''s hands yet, and the gap between the announcement and the bank transfer is where the next year of this story lives."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Texas money, and its condition"}]},{"type":"paragraph","content":[{"type":"text","text":"Texas appropriated $50 million for ibogaine research under SB 2308. The state had intended to run the programme with a pharmaceutical partner, and in March the Lieutenant Governor and the House Speaker announced it would instead be run by state researchers, after drug companies'' proposals failed to meet the state''s requirements. UTHealth Houston and UTMB were selected to lead a planned two-year trial covering addiction and traumatic brain injury."}]},{"type":"paragraph","content":[{"type":"text","text":"The condition is the part worth watching. As the Texas Tribune reported, an analyst said that without a private drug-company match the state may be unable to release the funds under the terms of SB 2308 at all, and that reaching FDA approval would likely take far more than $100 million in any case."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The federal order, and what it does not do"}]},{"type":"paragraph","content":[{"type":"text","text":"The executive order, titled Accelerating Medical Treatments for Serious Mental Illness, sets aside $50 million to widen veterans'' access to psychedelic treatment and directs the FDA to speed its review of substances including psilocybin and ibogaine. Ibogaine was the focus of the signing ceremony."}]},{"type":"paragraph","content":[{"type":"text","text":"What it does not do is reschedule the drug. Ibogaine remains Schedule I at the DEA, which is why the treatment described in every news story this year takes place outside the United States, and why Mexico, where it is unregulated rather than approved, remains the destination."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What to watch next"}]},{"type":"paragraph","content":[{"type":"text","text":"The FDA''s request for information on how an ibogaine trial should be designed closes to public comment on 20 November 2026. It is the first formal step toward a regulated pathway, and the questions it asks, particularly about cardiac screening and about what counts as a meaningful outcome, will shape whatever the Texas and federal money eventually pays for."}]},{"type":"paragraph","content":[{"type":"text","text":"Eye Today keeps a running record of every trial, grant and ruling, and of the legal status in each country."}]}]}'::jsonb,
       '<p>The headline number is $100 million: $50 million from Texas and at least $50 million attached to a federal executive order signed in April. Both are real. Neither is money in a researcher&rsquo;s hands yet, and the gap between the announcement and the bank transfer is where the next year of this story lives.</p><h2>The Texas money, and its condition</h2><p>Texas appropriated $50 million for ibogaine research under SB 2308. The state had intended to run the programme with a pharmaceutical partner, and in March the Lieutenant Governor and the House Speaker announced it would instead be run by state researchers, after drug companies&rsquo; proposals failed to meet the state&rsquo;s requirements. UTHealth Houston and UTMB were selected to lead a planned two-year trial covering addiction and traumatic brain injury.</p><p>The condition is the part worth watching. As <a href="https://www.texastribune.org/2026/03/31/texas-ibogaine-research-clinical-trials-psychedelics/">the Texas Tribune reported</a>, an analyst said that without a private drug-company match the state may be unable to release the funds under the terms of SB 2308 at all, and that reaching FDA approval would likely take far more than $100 million in any case.</p><h2>The federal order, and what it does not do</h2><p>The executive order, titled Accelerating Medical Treatments for Serious Mental Illness, sets aside $50 million to widen veterans&rsquo; access to psychedelic treatment and directs the FDA to speed its review of substances including psilocybin and ibogaine. Ibogaine was <a href="https://www.stripes.com/veterans/2026-04-20/ibogaine-treatment-psychedelics-executive-order-21432685.html">the focus of the signing ceremony</a>.</p><p>What it does not do is reschedule the drug. Ibogaine remains Schedule I at the DEA, which is why the treatment described in every news story this year takes place outside the United States, and why Mexico, where it is unregulated rather than approved, remains the destination.</p><h2>What to watch next</h2><p>The FDA&rsquo;s request for information on how an ibogaine trial should be designed closes to public comment on 20 November 2026. It is the first formal step toward a regulated pathway, and the questions it asks, particularly about cardiac screening and about what counts as a meaningful outcome, will shape whatever the Texas and federal money eventually pays for.</p><p>Eye Today keeps a running record of every <a href="https://theeye.today/tracker">trial, grant and ruling</a>, and of the <a href="https://theeye.today/legal-map">legal status in each country</a>.</p>',
       'draft',
       'Texas committed $50 million to ibogaine trials and a federal order promised as much again. Neither reschedules the drug, and the state money has a condition it has not met.'
  from public.sites s join public.sections sec on sec.site_id = s.id and sec.slug = 'policy-law'
 where s.slug = 'eyetoday'
on conflict (site_id, slug) do nothing;

select 'news links' as what, count(*)::text as n from public.news_links where status = 'draft'
union all
select 'new drafts', string_agg(slug, '; ') from public.articles
 where slug in ('ibogaine-has-gone-national-what-the-networks-are-saying', 'fifty-million-dollars-and-a-schedule-i-problem');
